content.content:
# Open a claim's editor (its edit button): the claim is locked for every other user until the editor
# is saved or cancelled, or the sheet's today changes. A claim another user has locked, one that is no
# longer a DRAFT, or one dated in a closed period is a 409 and takes no lock. Writes no audit line.
validate:
  class: net.officefloor.hq.app.claim.ValidateClaimLock
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.claim.ApplyClaimLock
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveClaimLock
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
  govern: [ transaction ]
# Defer an OPEN claim until a date after the sheet's today. Validate before Load so a bad date is a
# 400, not a 404; a claim not OPEN, a date not after today or a claim in a closed period is a 409
# and writes nothing.
validate:
  class: net.officefloor.hq.app.claim.ValidateClaimDefer
  next: snapshot
# Keep the figures as they were, so the change can audit the ones it moves.
snapshot:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.claim.ApplyClaimDefer
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveClaim
  govern: [ transaction ]
  next: record
# Audit only once the change is saved: a refused change writes no line.
record:
  class: net.officefloor.hq.app.claim.RecordClaimDeferred
  govern: [ transaction ]
  next: rollup
# After the change's own lines: a line per person whose figures moved, then the totals if they did.
rollup:
  class: net.officefloor.hq.app.rollup.RecordRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
  govern: [ transaction ]
package net.officefloor.hq.app.claim;

/** A claim's editor being opened or closed by `user`. */
public record ClaimLock(String user) {
}
package net.officefloor.hq.app.claim;

/** Body of opening or closing a claim's editor: who opens or closes it. */
public record ClaimLockRequest(String user) {
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.period.ClosedPeriods;
import net.officefloor.hq.app.period.PeriodClosedException;
import net.officefloor.plugin.variable.Val;

/** Opens the claim's editor for the user, locking the claim for everyone else; refused (taking no
 *  lock) when another user's editor locks it, it is no longer a DRAFT, or it is due by in a closed period. */
public class ApplyClaimLock {
    public void apply(@Val ClaimLock lock, @Val Claim claim, ClosedPeriods closedPeriods)
            throws ClaimLockedException, ClaimEditRefusedException, PeriodClosedException {
        refuseLocked(claim, lock.user());
        if (claim.getStatus() != ClaimStatus.DRAFT) {
            throw new ClaimEditRefusedException(claim.getStatus());
        }
        closedPeriods.refuse(claim.getSheetId(), claim.getDueBy());
        claim.setLockedBy(lock.user());
    }

    /** Refuse a change by `user` to a claim another user's open editor locks. */
    static void refuseLocked(Claim claim, String user) throws ClaimLockedException {
        String holder = claim.getLockedBy();
        if (holder != null && !holder.equals(user == null ? null : user.trim())) {
            throw new ClaimLockedException(holder);
        }
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;

/** A validated deferral: the date the claim is deferred until, and who defers it. */
public record ClaimDefer(LocalDate until, String user) {
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.period.ClosedPeriods;
import net.officefloor.hq.app.period.PeriodClosedException;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Val;

/** Defers an OPEN claim until a date after the sheet's today (a deferred one may be deferred again).
 *  A claim not OPEN, a date not after today, or a claim due by in a closed period is refused. */
public class ApplyClaimDefer {
    public void apply(@Val ClaimDefer change, @Val Claim claim, Sheets sheets, ClosedPeriods closedPeriods)
            throws ClaimStatusRefusedException, PeriodClosedException {
        closedPeriods.refuse(claim.getSheetId(), claim.getDueBy());
        if (claim.getStatus() != ClaimStatus.OPEN) {
